[
  {
    "title": "misaligned-half-points",
    "claim": "In Image #8, HasanAbi’s stacked half-point fraction extends well below the whole-number baseline in both the scoreboard and the central result.",
    "reason": "The staggered digits make the score harder to read at a glance.",
    "suggest": "Render the half point as an inline ½ glyph vertically centered beside the whole number."
  },
  {
    "title": "small-stick-captions",
    "claim": "In Image #3, the STANCE and TECHNIQUE caption letters are approximately 10 pixels tall at the stated 390-pixel viewport width.",
    "reason": "These essential control labels are difficult to read on a phone.",
    "suggest": "Set the captions to at least 18 CSS px and adjust their spacing to accommodate the larger text."
  },
  {
    "title": "duplicated-control-labels",
    "claim": "In Image #3, STANCE and TECHNIQUE appear both in the instruction strip and beneath the sticks, with the combined control area occupying approximately the bottom 274 pixels.",
    "reason": "Repeated labels consume space that could give the fighters more room.",
    "suggest": "Keep one label per stick and replace the separate instruction strip with concise instructions inside the control area."
  },
  {
    "title": "button-covers-foot",
    "claim": "In Image #2, the FIGHT button hides Asmongold’s forward foot while his rear foot remains visible.",
    "reason": "The opening composition obscures the fighter’s stance and connection to the floor.",
    "suggest": "Reserve a clear action row below the fighters and move their presentation upward enough to prevent overlap."
  },
  {
    "title": "kick-points-away",
    "claim": "In Image #18, Asmongold’s extended kicking foot points left while HasanAbi stands to his right.",
    "reason": "The winner’s displayed strike points away from the opponent, making the result pose visually confusing.",
    "suggest": "Replace the frozen kick on this result screen with a victory pose facing HasanAbi."
  }
]
